import { signal } from '@preact/signals';
import type { Lang } from './i18n';
import { online } from './network';

/**
 * Fixed audio prompts: /audio/{lang}/{key}.mp3, generated by
 * scripts/make-audio.mjs from the dictionaries. /audio/{lang}/index.json lists
 * the keys that have a file.
 *
 * Browsers block sound until the person taps the page, so the start screen's
 * first tap calls unlockAudio() (any first tap or key press does too). One
 * shared <audio> element is used for every prompt: iOS only lets an element
 * play later if it was first played from a tap.
 *
 * A missing file never shows an error. Order: the file for the language, then
 * a device voice for that language if one exists, otherwise silence.
 *
 * Caching: the service worker serves /audio/ cache-first at runtime. Nothing
 * is precached except the silent clip; warmAudio() fills the cache for the
 * chosen language in the background after the first screen.
 */
export const audioUnlocked = signal(false);
/** Id of the prompt or sequence playing now, or null. */
export const playingKey = signal<string | null>(null);

/** One clip in a spoken sequence. */
export interface SpeechItem {
  /** Audio file key: /audio/{lang}/{key}.mp3. */
  key: string;
  /** What the recording says; read by a device voice when there is no file. */
  text?: string | undefined;
  /** Language of this clip when it differs from the sequence (a server sentence). */
  lang?: Lang | undefined;
}

let element: HTMLAudioElement | null = null;
let ticket = 0;
let cancelClip: (() => void) | null = null;

function player(): HTMLAudioElement | null {
  if (typeof Audio === 'undefined') return null;
  if (!element) {
    element = new Audio();
    element.preload = 'auto';
  }
  return element;
}

// ---- manifest -------------------------------------------------------------------------------

const manifests = new Map<Lang, Promise<Set<string> | null>>();

/** Keys with a recording for this language, or null when the list cannot be loaded. */
export function audioKeys(code: Lang): Promise<Set<string> | null> {
  let pending = manifests.get(code);
  if (!pending) {
    pending = fetch(`/audio/${code}/index.json`, { credentials: 'same-origin' })
      .then((response) => (response.ok ? (response.json() as Promise<unknown>) : null))
      .then((data) => {
        const files = (data as { files?: unknown } | null)?.files;
        return files && typeof files === 'object' ? new Set(Object.keys(files)) : null;
      })
      .catch(() => null);
    manifests.set(code, pending);
    // Not loaded (offline, first visit): ask again next time.
    void pending.then((keys) => {
      if (!keys) manifests.delete(code);
    });
  }
  return pending;
}

// ---- playback -------------------------------------------------------------------------------

/** Call from the first tap handler (synchronously, inside the event). */
export function unlockAudio(): void {
  if (audioUnlocked.peek()) return;
  audioUnlocked.value = true;
  const audio = player();
  if (!audio) return;
  audio.src = '/audio/silence.mp3';
  audio.play().catch(() => {
    // A newer prompt replaced the silence, or the browser refused: both are fine.
  });
}

// Any first tap or key press unlocks sound, so a person who reloads on a later
// screen hears prompts again after one tap.
if (typeof document !== 'undefined') {
  const onFirst = (): void => unlockAudio();
  document.addEventListener('click', onFirst, { capture: true, once: true });
  document.addEventListener('keydown', onFirst, { capture: true, once: true });
}

export function stopAudio(): void {
  ticket += 1;
  cancelClip?.();
  cancelClip = null;
  element?.pause();
  if (typeof speechSynthesis !== 'undefined') speechSynthesis.cancel();
  playingKey.value = null;
}

type ClipResult = 'ended' | 'blocked' | 'failed';

function playFile(audio: HTMLAudioElement, src: string): Promise<ClipResult> {
  return new Promise<ClipResult>((resolve) => {
    let settled = false;
    const finish = (result: ClipResult): void => {
      if (settled) return;
      settled = true;
      audio.removeEventListener('ended', onEnded);
      audio.removeEventListener('error', onError);
      if (cancelClip === cancel) cancelClip = null;
      resolve(result);
    };
    const onEnded = (): void => finish('ended');
    const onError = (): void => finish('failed');
    const cancel = (): void => finish('blocked');
    audio.addEventListener('ended', onEnded);
    audio.addEventListener('error', onError);
    cancelClip = cancel;
    audio.src = src;
    audio.play().catch((error: unknown) => {
      const name = error instanceof DOMException ? error.name : '';
      // NotAllowedError: not unlocked yet. AbortError: replaced by a newer prompt.
      finish(name === 'NotAllowedError' || name === 'AbortError' ? 'blocked' : 'failed');
    });
  });
}

/** Read text with a device voice that really speaks this language. Never Urdu with an English voice. */
function speak(text: string | undefined, code: Lang): Promise<boolean> {
  if (!text || typeof speechSynthesis === 'undefined' || typeof SpeechSynthesisUtterance === 'undefined') {
    return Promise.resolve(false);
  }
  const voice = speechSynthesis
    .getVoices()
    .find((candidate) => candidate.lang.toLowerCase().replace('_', '-').startsWith(code));
  if (!voice) return Promise.resolve(false);
  return new Promise<boolean>((resolve) => {
    const utterance = new SpeechSynthesisUtterance(text.replace(/[⁦-⁩]/g, ''));
    utterance.voice = voice;
    utterance.lang = voice.lang;
    utterance.onend = () => resolve(true);
    utterance.onerror = () => resolve(true);
    speechSynthesis.speak(utterance);
  });
}

/**
 * Play clips one after another. `id` identifies the sequence for the speaker
 * button's playing state. A newer call or stopAudio() interrupts it.
 */
export function playSpeech(id: string, items: readonly SpeechItem[], code: Lang): void {
  const audio = player();
  if (!audio) return;
  stopAudio();
  const mine = ticket;
  playingKey.value = id;
  void (async () => {
    for (const item of items) {
      const clipLang = item.lang ?? code;
      const files = await audioKeys(clipLang);
      if (mine !== ticket) return;
      const hasFile = files === null || files.has(item.key);
      const result: ClipResult = hasFile ? await playFile(audio, `/audio/${clipLang}/${item.key}.mp3`) : 'failed';
      if (mine !== ticket) return;
      if (result === 'blocked') break;
      if (result === 'failed') await speak(item.text, clipLang);
    }
    if (mine === ticket) playingKey.value = null;
  })();
}

/**
 * Play the prompt for `key` in `code`. `spokenText` is what the recording says;
 * it is only used for the device-voice fallback.
 */
export function playPrompt(key: string, code: Lang, spokenText?: string): void {
  playSpeech(key, [{ key, text: spokenText }], code);
}

// ---- warming the cache ----------------------------------------------------------------------

/** Prompts of the application flow are fetched first. */
const FIRST = /^(start|home|consent|card|doc|name|household|income|widow|disability|aid|answer|review|submit|result|digit|count)_/;

const warming = new Set<Lang>();
let wanted: Lang | null = null;

/**
 * Fetch every recording of a language once, one at a time and at low
 * priority, so the service worker caches it for offline use. Production only
 * (no service worker in dev). Skipped when the person asked to save data.
 */
export function warmAudio(code: Lang): void {
  wanted = code;
  if (warming.has(code) || typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return;
  const connection = (navigator as Navigator & { connection?: { saveData?: boolean } }).connection;
  if (connection?.saveData) return;
  warming.add(code);
  void (async () => {
    let complete = false;
    try {
      const sw = navigator.serviceWorker;
      if (!sw.controller) {
        await new Promise<void>((resolve) => {
          sw.addEventListener('controllerchange', () => resolve(), { once: true });
          setTimeout(resolve, 20_000);
        });
      }
      if (!sw.controller) return; // dev server, or the worker is not active yet
      const files = await audioKeys(code);
      if (!files) return;
      const keys = [...files].sort((a, b) => Number(!FIRST.test(a)) - Number(!FIRST.test(b)));
      for (const key of keys) {
        if (!online.peek()) return;
        const response = await fetch(`/audio/${code}/${key}.mp3`, {
          credentials: 'same-origin',
          priority: 'low',
        } as RequestInit);
        await response.arrayBuffer(); // let the worker finish writing the cache entry
      }
      complete = true;
    } catch {
      // network dropped: try again when it is back
    } finally {
      if (!complete) warming.delete(code);
    }
  })();
}

online.subscribe((isOnline) => {
  if (isOnline && wanted && !warming.has(wanted)) warmAudio(wanted);
});
